import React from 'react';
import { Package, Puzzle, Bot, Webhook, Server, ExternalLink, FolderOpen } from 'lucide-react';
import { Badge } from './ui/badge';
import type { RepoPlugin } from './RepoPluginList';

interface RepoPluginDetailProps {
  plugin: RepoPlugin;
}

const scopeColors: Record<string, string> = {
  user: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',
  project: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  local: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
};

const scopeLabels: Record<string, string> = {
  user: 'User-level (all repos)',
  project: 'Project-level (this repo)',
  local: 'Local only (not committed)',
};

const RepoPluginDetail: React.FC<RepoPluginDetailProps> = ({ plugin }) => {
  const { components, manifest } = plugin;

  return (
    <div className="h-full overflow-auto">
      {/* Header */}
      <div className="p-6 border-b bg-background">
        <div className="flex items-start gap-4">
          <div className="p-3 rounded-lg bg-muted">
            <Package className="h-8 w-8 text-primary" />
          </div>
          <div className="flex-1">
            <div className="flex items-center gap-3">
              <h2 className="text-2xl font-bold">{plugin.name}</h2>
              <Badge variant="outline">{plugin.version}</Badge>
              <Badge className={scopeColors[plugin.scope]}>
                {scopeLabels[plugin.scope]}
              </Badge>
            </div>
            {plugin.description && (
              <p className="text-muted-foreground mt-2">{plugin.description}</p>
            )}
            {manifest.author && (
              <div className="flex items-center gap-2 mt-2 text-sm text-muted-foreground">
                <span>by {manifest.author.name || 'Unknown'}</span>
                {manifest.author.url && (
                  <a
                    href={manifest.author.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-1 text-primary hover:underline"
                  >
                    <ExternalLink className="h-3 w-3" />
                    Website
                  </a>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Path */}
        <div>
          <h3 className="text-sm font-medium text-muted-foreground mb-2 flex items-center gap-2">
            <FolderOpen className="h-4 w-4" />
            Plugin Location
          </h3>
          <code className="text-sm bg-muted px-3 py-2 rounded block overflow-x-auto">
            {plugin.path}
          </code>
        </div>

        {/* Components */}
        <div>
          <h3 className="text-lg font-semibold mb-4">Components</h3>

          {/* Skills */}
          {components.skills.length > 0 && (
            <div className="mb-4">
              <h4 className="text-sm font-medium text-muted-foreground mb-2 flex items-center gap-2">
                <Puzzle className="h-4 w-4" />
                Skills ({components.skills.length})
              </h4>
              <div className="flex flex-wrap gap-2">
                {components.skills.map(skill => (
                  <Badge key={skill} variant="secondary" className="text-sm">
                    /{skill}
                  </Badge>
                ))}
              </div>
            </div>
          )}

          {/* Agents */}
          {components.agents.length > 0 && (
            <div className="mb-4">
              <h4 className="text-sm font-medium text-muted-foreground mb-2 flex items-center gap-2">
                <Bot className="h-4 w-4" />
                Agents ({components.agents.length})
              </h4>
              <div className="flex flex-wrap gap-2">
                {components.agents.map(agent => (
                  <Badge key={agent} variant="secondary" className="text-sm">
                    {agent}
                  </Badge>
                ))}
              </div>
            </div>
          )}

          {/* Hooks */}
          {components.hasHooks && (
            <div className="mb-4">
              <h4 className="text-sm font-medium text-muted-foreground mb-2 flex items-center gap-2">
                <Webhook className="h-4 w-4" />
                Hooks
              </h4>
              <p className="text-sm text-muted-foreground">
                This plugin provides custom Claude hooks.
              </p>
            </div>
          )}

          {/* MCP */}
          {components.hasMcp && (
            <div className="mb-4">
              <h4 className="text-sm font-medium text-muted-foreground mb-2 flex items-center gap-2">
                <Server className="h-4 w-4" />
                MCP Server
              </h4>
              <p className="text-sm text-muted-foreground">
                This plugin provides an MCP server with tools.
              </p>
            </div>
          )}

          {/* No components */}
          {components.skills.length === 0 &&
           components.agents.length === 0 &&
           !components.hasHooks &&
           !components.hasMcp && (
            <p className="text-sm text-muted-foreground">
              No components discovered in this plugin.
            </p>
          )}
        </div>

        {/* Keywords */}
        {manifest.keywords && manifest.keywords.length > 0 && (
          <div>
            <h3 className="text-sm font-medium text-muted-foreground mb-2">Keywords</h3>
            <div className="flex flex-wrap gap-2">
              {manifest.keywords.map(keyword => (
                <Badge key={keyword} variant="outline" className="text-xs">
                  {keyword}
                </Badge>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default RepoPluginDetail;
