import React, { useState } from 'react';
import { Cloud, Bot } from 'lucide-react';
import { TinyBrainApiSection } from './settings/TinyBrainApiSection';
import { LlmApiSection } from './settings/LlmApiSection';

type SettingsSection = 'tiny-brain-api' | 'llm-api';

interface NavItemProps {
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  onClick: () => void;
}

const NavItem: React.FC<NavItemProps> = ({ icon, label, isActive, onClick }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-left transition-colors ${
      isActive
        ? 'bg-primary/10 text-primary dark:bg-primary/20'
        : 'hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300'
    }`}
  >
    {icon}
    <span className="font-medium">{label}</span>
  </button>
);

const SettingsPane: React.FC = () => {
  const [activeSection, setActiveSection] = useState<SettingsSection>('tiny-brain-api');

  const renderContent = () => {
    switch (activeSection) {
      case 'tiny-brain-api':
        return <TinyBrainApiSection />;
      case 'llm-api':
        return <LlmApiSection />;
      default:
        return null;
    }
  };

  return (
    <div className="flex h-full">
      {/* Sidebar */}
      <div className="w-64 border-r border-gray-200 dark:border-gray-700 p-4 flex-shrink-0">
        <nav className="space-y-1">
          <NavItem
            icon={<Cloud className="h-5 w-5" />}
            label="Tiny Brain API"
            isActive={activeSection === 'tiny-brain-api'}
            onClick={() => setActiveSection('tiny-brain-api')}
          />
          <NavItem
            icon={<Bot className="h-5 w-5" />}
            label="LLM API"
            isActive={activeSection === 'llm-api'}
            onClick={() => setActiveSection('llm-api')}
          />
        </nav>
      </div>

      {/* Content */}
      <div className="flex-1 p-8 overflow-auto">
        <div className="max-w-3xl">
          {renderContent()}
        </div>
      </div>
    </div>
  );
};

export default SettingsPane;
