import React, { useState, useEffect } from 'react';
import { Loader2, AlertCircle, CheckCircle2, XCircle, AlertTriangle, ChevronDown, ChevronRight, Settings, GitBranch, FileText, Key, FolderTree, RefreshCw } from 'lucide-react';
import type { ConfigHealth, HookStatus } from '../types';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from './ui/sheet';
import { Button } from './ui/button';

interface ConfigHealthPanelProps {
  isOpen: boolean;
  onClose: () => void;
  repoId: string;
  onRunAnalysis?: () => void;
}

const ConfigHealthPanel: React.FC<ConfigHealthPanelProps> = ({
  isOpen,
  onClose,
  repoId,
  onRunAnalysis,
}) => {
  const [health, setHealth] = useState<ConfigHealth | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['hooks', 'context', 'permissions', 'directories']));

  // Fetch health when panel opens
  useEffect(() => {
    if (isOpen && repoId) {
      fetchHealth();
    }
    if (!isOpen) {
      setHealth(null);
      setError(null);
    }
  }, [isOpen, repoId]);

  const fetchHealth = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/repos/${repoId}/config-health`);
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to fetch config health (${response.status})`);
      }
      const data = await response.json();
      setHealth(data.health);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const toggleSection = (section: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(section)) {
      newExpanded.delete(section);
    } else {
      newExpanded.add(section);
    }
    setExpandedSections(newExpanded);
  };

  const getStatusIcon = (status: 'healthy' | 'warning' | 'error') => {
    switch (status) {
      case 'healthy':
        return <CheckCircle2 className="h-5 w-5 text-green-500" />;
      case 'warning':
        return <AlertTriangle className="h-5 w-5 text-yellow-500" />;
      case 'error':
        return <XCircle className="h-5 w-5 text-red-500" />;
    }
  };

  const getStatusBg = (status: 'healthy' | 'warning' | 'error') => {
    switch (status) {
      case 'healthy':
        return 'from-green-50 to-emerald-50 dark:from-green-900/20 dark:to-emerald-900/20 border-green-100 dark:border-green-800';
      case 'warning':
        return 'from-yellow-50 to-amber-50 dark:from-yellow-900/20 dark:to-amber-900/20 border-yellow-100 dark:border-yellow-800';
      case 'error':
        return 'from-red-50 to-rose-50 dark:from-red-900/20 dark:to-rose-900/20 border-red-100 dark:border-red-800';
    }
  };

  const renderHookStatus = (hook: HookStatus) => {
    const isOk = hook.installed && hook.signed && hook.executable;
    return (
      <div className="flex items-center justify-between py-1.5">
        <span className="text-sm font-mono">{hook.name}</span>
        <div className="flex items-center gap-2">
          {isOk ? (
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          ) : (
            <div className="flex items-center gap-1 text-xs">
              {!hook.installed && <span className="text-red-500 px-1.5 py-0.5 bg-red-50 dark:bg-red-900/20 rounded">not installed</span>}
              {hook.installed && !hook.signed && <span className="text-yellow-500 px-1.5 py-0.5 bg-yellow-50 dark:bg-yellow-900/20 rounded">not signed</span>}
              {hook.installed && !hook.executable && <span className="text-yellow-500 px-1.5 py-0.5 bg-yellow-50 dark:bg-yellow-900/20 rounded">not executable</span>}
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-[480px] sm:max-w-[480px] overflow-y-auto">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2">
            <Settings className="h-5 w-5" />
            Configuration Health
          </SheetTitle>
          <SheetDescription>
            Validate tiny-brain configuration for this repository
          </SheetDescription>
        </SheetHeader>

        <div className="mt-4 space-y-4">
          {/* Refresh Button */}
          <div className="flex items-center gap-3">
            <Button
              variant="outline"
              onClick={fetchHealth}
              disabled={loading}
              className="flex-1"
            >
              {loading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Checking...
                </>
              ) : (
                <>
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Refresh
                </>
              )}
            </Button>
          </div>

          {/* Loading State */}
          {loading && !health && (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          )}

          {/* Error State */}
          {error && (
            <div className="flex items-start gap-3 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-red-700 dark:text-red-400">Error</p>
                <p className="text-sm text-red-600 dark:text-red-300 mt-1">{error}</p>
              </div>
            </div>
          )}

          {/* Health Content */}
          {!loading && !error && health && (
            <div className="space-y-4">
              {/* Summary Card */}
              <div className={`p-4 rounded-lg bg-gradient-to-r border ${getStatusBg(health.status)}`}>
                <div className="flex items-center gap-3">
                  {getStatusIcon(health.status)}
                  <div>
                    <p className="font-semibold capitalize">{health.status === 'healthy' ? 'All Good' : health.status === 'warning' ? 'Some Issues' : 'Configuration Issues'}</p>
                    <p className="text-sm text-gray-500 dark:text-gray-400">
                      {health.status === 'healthy'
                        ? 'Repository configuration is complete'
                        : 'Run /analyse to fix configuration'
                      }
                    </p>
                  </div>
                </div>
                {health.status !== 'healthy' && onRunAnalysis && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={onRunAnalysis}
                    className="mt-3 w-full"
                  >
                    Fix Configuration
                  </Button>
                )}
              </div>

              {/* Git Hooks Section */}
              <CollapsibleSection
                title="Git Hooks"
                icon={<GitBranch className="h-4 w-4" />}
                isExpanded={expandedSections.has('hooks')}
                onToggle={() => toggleSection('hooks')}
                status={
                  [health.hooks.preCommit, health.hooks.commitMsg, health.hooks.postCommit].every(h => h.installed && h.signed)
                    ? 'healthy' : 'error'
                }
              >
                <div className="space-y-1 divide-y divide-gray-100 dark:divide-gray-800">
                  {renderHookStatus(health.hooks.preCommit)}
                  {renderHookStatus(health.hooks.commitMsg)}
                  {renderHookStatus(health.hooks.postCommit)}
                </div>
              </CollapsibleSection>

              {/* CLAUDE.md Context Block Section */}
              <CollapsibleSection
                title="CLAUDE.md Context"
                icon={<FileText className="h-4 w-4" />}
                isExpanded={expandedSections.has('context')}
                onToggle={() => toggleSection('context')}
                status={health.contextBlock.present && health.contextBlock.upToDate ? 'healthy' : health.contextBlock.present ? 'warning' : 'error'}
              >
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Present</span>
                    <span className={health.contextBlock.present ? 'text-green-600 dark:text-green-400' : 'text-red-500'}>
                      {health.contextBlock.present ? 'Yes' : 'No'}
                    </span>
                  </div>
                  {health.contextBlock.present && (
                    <>
                      {health.contextBlock.version && (
                        <div className="flex justify-between text-sm">
                          <span className="text-gray-500 dark:text-gray-400">Version</span>
                          <span>{health.contextBlock.version}</span>
                        </div>
                      )}
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500 dark:text-gray-400">Up to Date</span>
                        <span className={health.contextBlock.upToDate ? 'text-green-600 dark:text-green-400' : 'text-yellow-500'}>
                          {health.contextBlock.upToDate ? 'Yes' : 'No'}
                        </span>
                      </div>
                    </>
                  )}
                  {health.contextBlock.missingSections.length > 0 && (
                    <div className="mt-2 pt-2 border-t border-gray-100 dark:border-gray-800">
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-1">Missing:</span>
                      <div className="flex flex-wrap gap-1">
                        {health.contextBlock.missingSections.map((section, i) => (
                          <span key={i} className="text-xs px-2 py-0.5 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded">
                            {section}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                  {health.contextBlock.error && (
                    <div className="text-xs text-red-500 mt-1">{health.contextBlock.error}</div>
                  )}
                </div>
              </CollapsibleSection>

              {/* Skill Permissions Section */}
              <CollapsibleSection
                title="Skill Permissions"
                icon={<Key className="h-4 w-4" />}
                isExpanded={expandedSections.has('permissions')}
                onToggle={() => toggleSection('permissions')}
                status={health.permissions.present && health.permissions.missing.length === 0 ? 'healthy' : 'error'}
              >
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Settings File</span>
                    <span className={health.permissions.present ? 'text-green-600 dark:text-green-400' : 'text-red-500'}>
                      {health.permissions.present ? 'Present' : 'Missing'}
                    </span>
                  </div>
                  {health.permissions.missing.length > 0 && (
                    <div className="mt-2 pt-2 border-t border-gray-100 dark:border-gray-800">
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-1">Missing permissions:</span>
                      <div className="flex flex-wrap gap-1">
                        {health.permissions.missing.map((perm, i) => (
                          <span key={i} className="text-xs font-mono px-2 py-0.5 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded">
                            {perm}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                  {health.permissions.error && (
                    <div className="text-xs text-red-500 mt-1">{health.permissions.error}</div>
                  )}
                </div>
              </CollapsibleSection>

              {/* Directories Section */}
              <CollapsibleSection
                title="Directory Structure"
                icon={<FolderTree className="h-4 w-4" />}
                isExpanded={expandedSections.has('directories')}
                onToggle={() => toggleSection('directories')}
                status={health.directories.missing.length === 0 ? 'healthy' : 'warning'}
              >
                <div className="space-y-2">
                  {health.directories.missing.length === 0 ? (
                    <div className="flex items-center gap-2 text-sm text-green-600 dark:text-green-400">
                      <CheckCircle2 className="h-4 w-4" />
                      All required directories present
                    </div>
                  ) : (
                    <>
                      <span className="text-xs text-gray-500 dark:text-gray-400 block mb-1">Missing directories:</span>
                      <div className="flex flex-wrap gap-1">
                        {health.directories.missing.map((dir, i) => (
                          <span key={i} className="text-xs font-mono px-2 py-0.5 bg-yellow-50 dark:bg-yellow-900/20 text-yellow-600 dark:text-yellow-400 rounded">
                            {dir}
                          </span>
                        ))}
                      </div>
                    </>
                  )}
                </div>
              </CollapsibleSection>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
};

// Helper Components
interface CollapsibleSectionProps {
  title: string;
  icon: React.ReactNode;
  isExpanded: boolean;
  onToggle: () => void;
  status: 'healthy' | 'warning' | 'error';
  children: React.ReactNode;
}

const CollapsibleSection: React.FC<CollapsibleSectionProps> = ({
  title,
  icon,
  isExpanded,
  onToggle,
  status,
  children
}) => (
  <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
    <button
      onClick={onToggle}
      className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800/50 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
    >
      <div className="flex items-center gap-2">
        {isExpanded ? (
          <ChevronDown className="h-4 w-4 text-gray-500" />
        ) : (
          <ChevronRight className="h-4 w-4 text-gray-500" />
        )}
        {icon}
        <span className="font-medium text-sm">{title}</span>
      </div>
      <div className="flex items-center">
        {status === 'healthy' && <CheckCircle2 className="h-4 w-4 text-green-500" />}
        {status === 'warning' && <AlertTriangle className="h-4 w-4 text-yellow-500" />}
        {status === 'error' && <XCircle className="h-4 w-4 text-red-500" />}
      </div>
    </button>
    {isExpanded && (
      <div className="p-3 bg-white dark:bg-gray-900">
        {children}
      </div>
    )}
  </div>
);

export default ConfigHealthPanel;
