import React, { useState } from 'react';
import { createPortal } from 'react-dom';
import { archivePlan, unarchivePlan, activatePlan, deletePlan } from '../services/api';
import type { Plan } from '../types';

interface PlanActionsProps {
  selectedPlan: Plan | null;
  onRefresh?: () => void; // Made optional - SSE will handle updates
}

const PlanActions: React.FC<PlanActionsProps> = ({ 
  selectedPlan
}) => {
  const [loading, setLoading] = useState<string | null>(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const handleArchive = async () => {
    if (!selectedPlan) return;
    
    try {
      setLoading('archive');
      await archivePlan(selectedPlan.id);
      // SSE will handle the UI update - no need to refresh
      console.log('[PlanActions] Plan archived, waiting for SSE update');
    } catch (error) {
      console.error('Failed to archive plan:', error);
      alert('Failed to archive plan');
    } finally {
      setLoading(null);
    }
  };

  const handleUnarchive = async () => {
    if (!selectedPlan) return;
    
    try {
      setLoading('unarchive');
      await unarchivePlan(selectedPlan.id);
      // SSE will handle the UI update - no need to refresh
      console.log('[PlanActions] Plan unarchived, waiting for SSE update');
    } catch (error) {
      console.error('Failed to unarchive plan:', error);
      alert('Failed to unarchive plan');
    } finally {
      setLoading(null);
    }
  };

  const handleActivate = async () => {
    if (!selectedPlan) return;
    
    console.log('[PlanActions] Set as Current clicked');
    console.log('[PlanActions] Current active plan ID:', selectedPlan.isTheCurrentPlan ? selectedPlan.id : 'None');
    console.log('[PlanActions] Plan to activate:', selectedPlan.id);
    
    try {
      setLoading('activate');
      console.log('[PlanActions] Calling activatePlan API...');
      await activatePlan(selectedPlan.id);
      console.log('[PlanActions] API call successful, plan activated:', selectedPlan.id);
      // SSE will handle the UI update - no need to refresh
      console.log('[PlanActions] Waiting for SSE update...');
    } catch (error) {
      console.error('[PlanActions] Failed to activate plan:', error);
      alert('Failed to activate plan');
    } finally {
      setLoading(null);
      console.log('[PlanActions] Activation process complete');
    }
  };

  const handleDelete = async () => {
    if (!selectedPlan) return;
    
    try {
      setLoading('delete');
      await deletePlan(selectedPlan.id);
      setShowDeleteConfirm(false);
      // SSE will handle the UI update - no need to refresh
      console.log('[PlanActions] Plan deleted, waiting for SSE update');
    } catch (error) {
      console.error('Failed to delete plan:', error);
      alert('Failed to delete plan');
    } finally {
      setLoading(null);
    }
  };

  if (!selectedPlan) {
    return null;
  }

  // Check plan type and current status
  const isArchived = selectedPlan.type === 'archived';
  const isTheCurrentPlan = selectedPlan.isTheCurrentPlan;
  const isActiveType = selectedPlan.type === 'active';

  return (
    <>
      <div className="flex items-center gap-2">
        {/* Archive/Unarchive button */}
        {!isArchived ? (
          <button
            onClick={handleArchive}
            disabled={loading !== null}
            className="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors
              bg-yellow-500/10 hover:bg-yellow-500/20 text-yellow-700 dark:text-yellow-300
              border border-yellow-500/30 hover:border-yellow-500/50
              disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Archive plan"
          >
            {loading === 'archive' ? 'Archiving...' : 'Archive'}
          </button>
        ) : (
          <button
            onClick={handleUnarchive}
            disabled={loading !== null}
            className="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors
              bg-blue-500/10 hover:bg-blue-500/20 text-blue-700 dark:text-blue-300
              border border-blue-500/30 hover:border-blue-500/50
              disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Unarchive plan"
          >
            {loading === 'unarchive' ? 'Unarchiving...' : 'Unarchive'}
          </button>
        )}

        {/* Set as Current button (for active plans that aren't the current plan) */}
        {isActiveType && !isTheCurrentPlan && (
          <button
            onClick={handleActivate}
            disabled={loading !== null}
            className="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors
              bg-green-500/10 hover:bg-green-500/20 text-green-700 dark:text-green-300
              border border-green-500/30 hover:border-green-500/50
              disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Set as current plan"
          >
            {loading === 'activate' ? 'Setting...' : 'Set as Current'}
          </button>
        )}

        {/* Delete button (only for archived plans) */}
        {isArchived && (
          <button
            onClick={() => setShowDeleteConfirm(true)}
            disabled={loading !== null}
            className="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors
              bg-red-500/10 hover:bg-red-500/20 text-red-700 dark:text-red-300
              border border-red-500/30 hover:border-red-500/50
              disabled:opacity-50 disabled:cursor-not-allowed"
            aria-label="Delete plan"
          >
            {loading === 'delete' ? 'Deleting...' : 'Delete'}
          </button>
        )}
      </div>

      {/* Delete Confirmation Dialog - Rendered via Portal */}
      {showDeleteConfirm && createPortal(
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50" onClick={() => setShowDeleteConfirm(false)}>
          <div className="bg-bg-primary dark:bg-gray-800 rounded-lg shadow-xl border border-border dark:border-gray-700 p-6 max-w-md w-full mx-4" onClick={e => e.stopPropagation()}>
            <h3 className="text-lg font-semibold text-text-primary dark:text-gray-100 mb-4">
              Delete Plan?
            </h3>
            
            <p className="text-sm text-text-secondary dark:text-gray-400 mb-6">
              Are you sure you want to permanently delete "{selectedPlan.name}"? This action cannot be undone.
            </p>
            
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setShowDeleteConfirm(false)}
                className="px-4 py-2 text-sm font-medium rounded-lg transition-colors
                  bg-gray-500/10 hover:bg-gray-500/20 text-gray-700 dark:text-gray-300
                  border border-gray-500/30 hover:border-gray-500/50"
              >
                Cancel
              </button>
              <button
                onClick={handleDelete}
                disabled={loading === 'delete'}
                className="px-4 py-2 text-sm font-medium rounded-lg transition-colors
                  bg-red-500 hover:bg-red-600 text-white
                  disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading === 'delete' ? 'Deleting...' : 'Delete Plan'}
              </button>
            </div>
          </div>
        </div>,
        document.body
      )}
    </>
  );
};

export default PlanActions;