import { useState, useEffect } from 'react';

interface ApiKeyStatus {
  hasLlmApiKey: boolean;
  isLoading: boolean;
  error: string | null;
}

export function useApiKeyStatus(): ApiKeyStatus {
  const [hasLlmApiKey, setHasLlmApiKey] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkApiKeyStatus = async () => {
      try {
        const response = await fetch('/api/config/credentials');
        if (!response.ok) {
          setHasLlmApiKey(false);
          setIsLoading(false);
          return;
        }
        const data = await response.json();
        setHasLlmApiKey(data.hasLlmApiKey ?? false);
        setError(null);
      } catch (err) {
        setHasLlmApiKey(false);
        setError('Failed to check API key status');
      } finally {
        setIsLoading(false);
      }
    };

    checkApiKeyStatus();
  }, []);

  return { hasLlmApiKey, isLoading, error };
}
