import { cn } from "@/lib/utils"

interface AnimatedGradientButtonProps {
  children: React.ReactNode
  className?: string
  onClick?: () => void
  animated?: boolean
}

export function AnimatedGradientButton({
  children,
  className,
  onClick,
  animated = true
}: AnimatedGradientButtonProps) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "group relative flex items-center justify-center rounded-lg px-4 py-1.5",
        "shadow-[inset_0_-8px_10px_#8fdfff1f] transition-shadow duration-500 ease-out",
        "hover:shadow-[inset_0_-5px_10px_#8fdfff3f]",
        className
      )}
    >
      <span
        className={cn(
          "absolute inset-0 block h-full w-full rounded-[inherit]",
          "bg-gradient-to-r from-[#ffaa40]/50 via-[#9c40ff]/50 to-[#ffaa40]/50",
          "bg-[length:300%_100%] p-[1px]",
          animated && "animate-gradient"
        )}
        style={{
          WebkitMask:
            "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
          WebkitMaskComposite: "destination-out",
          mask: "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
          maskComposite: "subtract",
        }}
      />
      <span className="relative flex items-center gap-2 text-sm font-medium">
        {children}
      </span>
    </button>
  )
}
