import React from 'react';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter
} from './ui/sheet';
import { Button } from './ui/button';
import { Loader2, AlertCircle, CheckCircle, ChevronDown, ChevronRight, Wrench } from 'lucide-react';
import type { SkillName, ToolCall } from '../types';

interface SkillInvocationPanelProps {
  isOpen: boolean;
  onClose: () => void;
  skillName: SkillName;
  output: string;
  toolCalls: ToolCall[];
  isRunning: boolean;
  error: string | null;
  onCancel: () => void;
}

const skillLabels: Record<SkillName, string> = {
  fix: 'Creating Fix',
  plan: 'Creating PRD',
  feature: 'Adding Feature',
  adr: 'Creating ADR',
  quality: 'Running Quality Analysis'
};

export const SkillInvocationPanel: React.FC<SkillInvocationPanelProps> = ({
  isOpen,
  onClose,
  skillName,
  output,
  toolCalls,
  isRunning,
  error,
  onCancel
}) => {
  const [toolCallsExpanded, setToolCallsExpanded] = React.useState(true);

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-[500px] sm:max-w-[500px] flex flex-col">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2">
            {skillLabels[skillName] || `Running ${skillName}`}
            {isRunning && (
              <span className="inline-flex items-center gap-1 text-sm font-normal text-blue-600 dark:text-blue-400">
                <Loader2 className="h-4 w-4 animate-spin" />
                Running...
              </span>
            )}
          </SheetTitle>
          <SheetDescription>
            Skill invocation via Claude API
          </SheetDescription>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto py-4 space-y-4">
          {/* Error display */}
          {error && (
            <div className="flex items-start gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
              <div className="text-sm text-red-700 dark:text-red-300">{error}</div>
            </div>
          )}

          {/* Output area */}
          <div className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4 min-h-[200px] max-h-[400px] overflow-y-auto">
            {output ? (
              <pre className="whitespace-pre-wrap text-sm text-gray-800 dark:text-gray-200 font-mono">
                {output}
              </pre>
            ) : (
              <p className="text-sm text-gray-500 dark:text-gray-400 italic">
                {isRunning ? 'Waiting for output...' : 'No output yet'}
              </p>
            )}
          </div>

          {/* Tool calls section */}
          {toolCalls.length > 0 && (
            <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
              <button
                onClick={() => setToolCallsExpanded(!toolCallsExpanded)}
                className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800/50 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              >
                <div className="flex items-center gap-2">
                  {toolCallsExpanded ? (
                    <ChevronDown className="h-4 w-4 text-gray-500" />
                  ) : (
                    <ChevronRight className="h-4 w-4 text-gray-500" />
                  )}
                  <Wrench className="h-4 w-4 text-gray-500" />
                  <span className="font-medium text-gray-900 dark:text-gray-100">
                    Tool Calls
                  </span>
                  <span className="text-sm text-gray-500 dark:text-gray-400">
                    ({toolCalls.length})
                  </span>
                </div>
              </button>

              {toolCallsExpanded && (
                <div className="divide-y divide-gray-200 dark:divide-gray-700">
                  {toolCalls.map((call, idx) => (
                    <div
                      key={idx}
                      className="p-3 bg-white dark:bg-gray-900 flex items-start gap-2"
                    >
                      <div className="flex-shrink-0 mt-0.5">
                        {call.result ? (
                          call.result.success ? (
                            <CheckCircle className="h-4 w-4 text-green-500" />
                          ) : (
                            <AlertCircle className="h-4 w-4 text-red-500" />
                          )
                        ) : (
                          <Loader2 className="h-4 w-4 text-blue-500 animate-spin" />
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <span className="font-mono text-sm text-gray-900 dark:text-gray-100">
                          {call.tool}
                        </span>
                        <div className="text-xs text-gray-500 dark:text-gray-400 truncate mt-0.5">
                          {JSON.stringify(call.input).slice(0, 100)}
                          {JSON.stringify(call.input).length > 100 && '...'}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        <SheetFooter className="flex-shrink-0">
          {isRunning ? (
            <Button variant="destructive" onClick={onCancel}>
              Cancel
            </Button>
          ) : (
            <Button variant="outline" onClick={onClose} aria-label="Close">
              Close
            </Button>
          )}
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
};

export default SkillInvocationPanel;
