import React from 'react';
import {
  Shield,
  HeartPulse,
  Zap,
  Wrench,
  TestTube,
  Boxes,
  FileText,
  Settings,
  LucideIcon,
} from 'lucide-react';
import type { QualityIssue } from '../types';

interface CategoryConfig {
  name: string;
  weight: number;
  icon: LucideIcon;
  color: string;
  bgColor: string;
}

const categories: CategoryConfig[] = [
  { name: 'Security', weight: 15, icon: Shield, color: 'text-red-500', bgColor: 'bg-red-500/10' },
  { name: 'Reliability', weight: 10, icon: HeartPulse, color: 'text-blue-500', bgColor: 'bg-blue-500/10' },
  { name: 'Performance', weight: 10, icon: Zap, color: 'text-yellow-500', bgColor: 'bg-yellow-500/10' },
  { name: 'Maintainability', weight: 5, icon: Wrench, color: 'text-cyan-500', bgColor: 'bg-cyan-500/10' },
  { name: 'Testing', weight: 5, icon: TestTube, color: 'text-purple-500', bgColor: 'bg-purple-500/10' },
  { name: 'Architecture', weight: 5, icon: Boxes, color: 'text-orange-500', bgColor: 'bg-orange-500/10' },
  { name: 'Documentation', weight: 3, icon: FileText, color: 'text-blue-400', bgColor: 'bg-blue-400/10' },
  { name: 'Operations', weight: 3, icon: Settings, color: 'text-gray-500', bgColor: 'bg-gray-500/10' },
];

interface QualityCategoryGridProps {
  issues?: QualityIssue[];
}

export const QualityCategoryGrid: React.FC<QualityCategoryGridProps> = ({ issues = [] }) => {
  // Count issues per category
  const issueCounts = issues.reduce((acc, issue) => {
    acc[issue.category] = (acc[issue.category] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <div className="grid grid-cols-4 gap-3">
      {categories.map((category) => {
        const Icon = category.icon;
        const issueCount = issueCounts[category.name] || 0;

        return (
          <div
            key={category.name}
            className="relative rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50 p-3 text-center hover:border-purple-500/50 transition-colors"
          >
            <div className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${category.bgColor} mb-2`}>
              <Icon className={`h-4 w-4 ${category.color}`} />
            </div>
            <div className={`text-lg font-bold ${issueCount > 0 ? 'text-red-600 dark:text-red-400' : 'text-gray-400 dark:text-gray-500'}`}>
              {issueCount}
            </div>
            <div className="text-xs text-gray-500 dark:text-gray-400">
              {category.name}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default QualityCategoryGrid;
