import { Webhook, GitBranch, Settings } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Hook, AllHooks } from '@/types'

interface HooksListProps {
  hooks: AllHooks
  selectedHook: Hook | null
  onSelectHook: (hook: Hook) => void
}

export default function HooksList({ hooks, selectedHook, onSelectHook }: HooksListProps) {
  const hasPluginHooks = hooks.pluginHooks.length > 0
  const hasGitHooks = hooks.gitHooks.length > 0
  const isEmpty = !hasPluginHooks && !hasGitHooks

  if (isEmpty) {
    return (
      <div className="flex flex-col items-center justify-center p-8 text-muted-foreground">
        <Webhook className="h-12 w-12 mb-4 opacity-50" />
        <p className="text-sm">No hooks configured</p>
        <p className="text-xs mt-1">Add hooks to automate workflows</p>
      </div>
    )
  }

  return (
    <div className="divide-y divide-border">
      {/* Plugin Hooks Section */}
      {hasPluginHooks && (
        <div>
          <div className="px-4 py-2 bg-muted/50 flex items-center gap-2">
            <Settings className="h-4 w-4 text-muted-foreground" />
            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
              Plugin Hooks ({hooks.pluginHooks.length})
            </span>
          </div>
          {hooks.pluginHooks.map((hook) => (
            <HookItem
              key={`plugin-${hook.name}`}
              hook={hook}
              isSelected={selectedHook?.name === hook.name && selectedHook?.type === 'plugin'}
              onSelect={() => onSelectHook(hook)}
            />
          ))}
        </div>
      )}

      {/* Git Hooks Section */}
      {hasGitHooks && (
        <div>
          <div className="px-4 py-2 bg-muted/50 flex items-center gap-2">
            <GitBranch className="h-4 w-4 text-muted-foreground" />
            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
              Git Hooks ({hooks.gitHooks.length})
            </span>
          </div>
          {hooks.gitHooks.map((hook) => (
            <HookItem
              key={`git-${hook.name}`}
              hook={hook}
              isSelected={selectedHook?.name === hook.name && selectedHook?.type === 'git'}
              onSelect={() => onSelectHook(hook)}
            />
          ))}
        </div>
      )}
    </div>
  )
}

interface HookItemProps {
  hook: Hook
  isSelected: boolean
  onSelect: () => void
}

function HookItem({ hook, isSelected, onSelect }: HookItemProps) {
  return (
    <button
      onClick={onSelect}
      className={cn(
        'w-full px-4 py-3 text-left transition-colors',
        'hover:bg-accent/50',
        isSelected && 'bg-accent border-l-2 border-primary'
      )}
    >
      <div className="flex items-center justify-between">
        <div className="flex-1 min-w-0">
          <div className="font-medium text-sm truncate">{hook.name}</div>
          <div className="text-xs text-muted-foreground flex items-center gap-2 mt-0.5">
            <span>{hook.event}</span>
            {hook.matcher && (
              <>
                <span className="text-muted-foreground/50">|</span>
                <span className="truncate" title={hook.matcher}>
                  matcher: {hook.matcher}
                </span>
              </>
            )}
          </div>
        </div>
        <div className={cn(
          'text-xs px-2 py-0.5 rounded-full',
          hook.type === 'plugin' ? 'bg-purple-500/10 text-purple-500' : 'bg-orange-500/10 text-orange-500'
        )}>
          {hook.type}
        </div>
      </div>
    </button>
  )
}
