import { useState, useCallback, useRef } from 'react';
import type { SkillName, SkillInvocationContext, ToolCall } from '../types';
import { parseSSEStream } from '../utils/sse-parser';

export interface UseSkillInvocationResult {
  invoke: (skill: SkillName, prompt: string, context?: SkillInvocationContext) => Promise<void>;
  cancel: () => void;
  isRunning: boolean;
  output: string;
  toolCalls: ToolCall[];
  error: string | null;
  sessionId: string | null;
}

/**
 * React hook for invoking skills with SSE streaming
 */
export function useSkillInvocation(): UseSkillInvocationResult {
  const [isRunning, setIsRunning] = useState(false);
  const [output, setOutput] = useState('');
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);

  const invoke = useCallback(async (
    skill: SkillName,
    prompt: string,
    context?: SkillInvocationContext
  ): Promise<void> => {
    // Cancel any existing invocation
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Reset state
    setOutput('');
    setToolCalls([]);
    setError(null);
    setSessionId(null);
    setIsRunning(true);

    // Create new abort controller
    abortControllerRef.current = new AbortController();

    try {
      const response = await fetch('/api/skills/invoke', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ skill, prompt, context }),
        signal: abortControllerRef.current.signal
      });

      // Handle error responses
      if (!response.ok) {
        const errorData = await response.json();
        setError(errorData.error || `HTTP error ${response.status}`);
        setIsRunning(false);
        return;
      }

      // Process SSE stream
      const reader = response.body?.getReader();
      if (!reader) {
        setError('No response body');
        setIsRunning(false);
        return;
      }

      const decoder = new TextDecoder();
      let buffer = '';

      // eslint-disable-next-line no-constant-condition
      while (true) {
        const { done, value } = await reader.read();

        if (done) {
          break;
        }

        buffer += decoder.decode(value, { stream: true });

        // Parse events from buffer
        const { events, buffer: remaining } = parseSSEStream(buffer);
        buffer = remaining;

        // Process each event
        for (const event of events) {
          switch (event.event) {
            case 'text': {
              const data = event.data as { text: string };
              setOutput(prev => prev + data.text);
              break;
            }

            case 'tool_use': {
              const data = event.data as { tool: string; input: Record<string, unknown> };
              setToolCalls(prev => [...prev, {
                tool: data.tool,
                input: data.input
              }]);
              break;
            }

            case 'tool_result': {
              const data = event.data as {
                toolId: string;
                success: boolean;
                result?: string;
                error?: string;
              };
              // Update the most recent tool call with its result
              setToolCalls(prev => {
                const updated = [...prev];
                // Find the last tool call without a result and update it
                for (let i = updated.length - 1; i >= 0; i--) {
                  if (!updated[i].result) {
                    updated[i] = {
                      ...updated[i],
                      id: data.toolId,
                      result: {
                        success: data.success,
                        result: data.result,
                        error: data.error
                      }
                    };
                    break;
                  }
                }
                return updated;
              });
              break;
            }

            case 'complete': {
              const data = event.data as { success: boolean; sessionId: string };
              setSessionId(data.sessionId);
              setIsRunning(false);
              break;
            }

            case 'error': {
              const data = event.data as { error: string };
              setError(data.error);
              setIsRunning(false);
              break;
            }
          }
        }
      }
    } catch (err) {
      if (err instanceof Error && err.name === 'AbortError') {
        // Cancellation - don't set error
        setIsRunning(false);
        return;
      }
      setError(err instanceof Error ? err.message : 'Unknown error');
      setIsRunning(false);
    }
  }, []);

  const cancel = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setIsRunning(false);
  }, []);

  return {
    invoke,
    cancel,
    isRunning,
    output,
    toolCalls,
    error,
    sessionId
  };
}
