import React from 'react';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, Circle, TestTube2, GitCommit, FastForward, TestTube, RefreshCw, ExternalLink, FileCode, Wrench, AlertCircle } from 'lucide-react';
import { formatDistanceToNow, format } from 'date-fns';
import type { Fix, FixTask } from '../types';
import TestPlanBadge from './TestPlanBadge';
import TestPlanDetail from './TestPlanDetail';
import CommitDetailsPopover from './CommitDetailsPopover';

interface FixDetailProps {
  fix: Fix;
  repoId: string;
}

const severityColors = {
  low: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300',
  medium: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300',
  high: 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300',
  critical: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300',
};

const statusLabels = {
  investigating: 'Investigating',
  in_progress: 'In Progress',
  resolved: 'Resolved',
};

const statusColors = {
  investigating: 'bg-yellow-500',
  in_progress: 'bg-blue-500',
  resolved: 'bg-green-500',
};

// Format date for display (e.g., "7th Jan 2026 15:17")
// Handles both date-only (2026-01-07) and full ISO timestamps
function formatDateTime(dateStr: string): string {
  const date = new Date(dateStr);
  // If it's a date-only string, don't show time
  if (dateStr.length === 10 && !dateStr.includes('T')) {
    return format(date, "do MMM yyyy");
  }
  return format(date, "do MMM yyyy HH:mm");
}

// Render relative time with bold relative part and full date
// Handles both date-only (2026-01-07) and full ISO timestamps
const RelativeDateTime: React.FC<{ dateStr: string; prefix?: string }> = ({ dateStr, prefix }) => {
  const date = new Date(dateStr);
  const relative = formatDistanceToNow(date, { addSuffix: true });
  // If it's a date-only string, don't show time in absolute
  const isDateOnly = dateStr.length === 10 && !dateStr.includes('T');
  const absolute = format(date, isDateOnly ? "do MMM yyyy" : "do MMM yyyy HH:mm");
  return (
    <span className="text-muted-foreground">
      {prefix && `${prefix} `}<span className="font-semibold">{relative}</span> ({absolute})
    </span>
  );
};

const TaskItem: React.FC<{ task: FixTask; index: number; repoId: string }> = ({ task, index, repoId }) => {
  const getStatusIcon = () => {
    switch (task.status) {
      case 'completed':
        return <CheckCircle2 className="h-5 w-5 text-green-500" />;
      case 'superseded':
        return <FastForward className="h-5 w-5 text-blue-500" />;
      case 'tested':
        return <TestTube2 className="h-5 w-5 text-yellow-500" />;
      default:
        return <Circle className="h-5 w-5 text-muted-foreground" />;
    }
  };

  return (
    <div className="flex items-start gap-3 p-3 rounded-lg bg-muted/50">
      <div className="flex-shrink-0 mt-0.5">
        {getStatusIcon()}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium text-muted-foreground">
            {index + 1}.
          </span>
          <span className="font-medium">{task.description}</span>
        </div>

        {/* TDD Phase commits */}
        <div className="mt-2 flex flex-wrap items-center gap-3 text-xs group">
          {/* Test Phase (Red) */}
          {task.testCommitSha && (
            <div className="flex items-center gap-2">
              <CommitDetailsPopover
                commitSha={task.testCommitSha}
                commitType="test"
                repoId={repoId}
              >
                <span className="text-red-600 hover:text-red-800 dark:text-red-400 dark:hover:text-red-300 font-mono flex items-center gap-1 cursor-pointer">
                  <TestTube className="h-3 w-3" />
                  {task.testCommitSha.substring(0, 7)}
                  <ExternalLink className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                </span>
              </CommitDetailsPopover>
              {/* Show completion on test commit if no impl commit exists */}
              {task.completedAt && !task.commitSha && (
                <RelativeDateTime dateStr={task.completedAt} prefix="Completed" />
              )}
            </div>
          )}

          {/* Implementation Phase (Green) */}
          {task.commitSha && (
            <div className="flex items-center gap-2">
              <CommitDetailsPopover
                commitSha={task.commitSha}
                commitType="feat"
                repoId={repoId}
              >
                <span className="text-green-600 hover:text-green-800 dark:text-green-400 dark:hover:text-green-300 font-mono flex items-center gap-1 cursor-pointer">
                  <GitCommit className="h-3 w-3" />
                  {task.commitSha.substring(0, 7)}
                  <ExternalLink className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                </span>
              </CommitDetailsPopover>
              {/* Show completion on impl commit */}
              {task.completedAt && (
                <RelativeDateTime dateStr={task.completedAt} prefix="Completed" />
              )}
            </div>
          )}

          {/* Refactor Phase */}
          {task.refactorCommitSha && (
            <CommitDetailsPopover
              commitSha={task.refactorCommitSha}
              commitType="refactor"
              repoId={repoId}
            >
              <span className="text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 font-mono flex items-center gap-1 cursor-pointer">
                <RefreshCw className="h-3 w-3" />
                {task.refactorCommitSha.substring(0, 7)}
                <ExternalLink className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
              </span>
            </CommitDetailsPopover>
          )}
        </div>
      </div>
    </div>
  );
};

const FixDetail: React.FC<FixDetailProps> = ({ fix, repoId }) => {
  const completedTasks = fix.tasks.filter(t => t.status === 'completed' || t.status === 'superseded').length;
  const totalTasks = fix.tasks.length;
  const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  return (
    <div className="p-6 space-y-6 overflow-auto h-full">
      {/* Header */}
      <div className="space-y-3">
        <div className="flex items-start justify-between gap-4">
          <h2 className="text-2xl font-bold">{fix.title}</h2>
          <div className="flex items-center gap-2">
            <Badge className={cn(severityColors[fix.severity])}>
              {fix.severity}
            </Badge>
            <Badge variant="outline" className="flex items-center gap-1.5">
              <span className={cn('w-2 h-2 rounded-full', statusColors[fix.status])} />
              {statusLabels[fix.status]}
            </Badge>
          </div>
        </div>
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">{fix.id}</span>
          <span className="text-xs text-muted-foreground font-mono">{fix.filePath}</span>
        </div>

        {/* Dates - inline */}
        <div className="flex items-center gap-4 text-sm text-muted-foreground">
          {fix.reported && (
            <span>Reported: {formatDateTime(fix.reported)}</span>
          )}
          {fix.resolved && (
            <span className="flex items-center gap-1">
              <span>Resolved:</span>
              <span className="font-semibold text-green-600 dark:text-green-400">
                {formatDistanceToNow(new Date(fix.resolved), { addSuffix: true })}
              </span>
            </span>
          )}
        </div>

        {/* Progress */}
        {totalTasks > 0 && (
          <div>
            <div className="flex items-center justify-between text-sm mb-2">
              <span className="text-muted-foreground">Progress</span>
              <span className="font-medium">{completedTasks}/{totalTasks} tasks ({progress}%)</span>
            </div>
            <div className="h-2 bg-muted rounded-full overflow-hidden">
              <div
                className={cn(
                  'h-full rounded-full transition-all',
                  fix.status === 'resolved' ? 'bg-green-500' : 'bg-primary'
                )}
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {/* Test Plan Summary */}
        {fix.testPlan && (
          <div className="flex items-center gap-2">
            <span className="text-sm text-muted-foreground">Tests:</span>
            <TestPlanBadge testPlan={fix.testPlan} />
          </div>
        )}
      </div>

      {/* Resolution Details - shown above tasks for resolved fixes */}
      {fix.resolution && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-lg flex items-center gap-2">
              <CheckCircle2 className="h-5 w-5 text-green-500" />
              Resolution
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Root Cause */}
            {fix.resolution.rootCause && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <AlertCircle className="h-4 w-4" />
                  Root Cause
                </h4>
                <p className="text-sm pl-6">{fix.resolution.rootCause}</p>
              </div>
            )}

            {/* Fix Steps */}
            {fix.resolution.fix && fix.resolution.fix.length > 0 && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <Wrench className="h-4 w-4" />
                  Fix Applied
                </h4>
                <ol className="text-sm pl-6 space-y-1 list-decimal list-inside">
                  {fix.resolution.fix.map((step, i) => (
                    <li key={i} className="text-sm">{step}</li>
                  ))}
                </ol>
              </div>
            )}

            {/* Files Modified */}
            {fix.resolution.filesModified && fix.resolution.filesModified.length > 0 && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <FileCode className="h-4 w-4" />
                  Files Modified ({fix.resolution.filesModified.length})
                </h4>
                <ul className="text-xs pl-6 space-y-0.5 font-mono">
                  {fix.resolution.filesModified.map((file, i) => (
                    <li key={i} className="text-muted-foreground">{file}</li>
                  ))}
                </ul>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Test Plan Detail */}
      <TestPlanDetail testPlan={fix.testPlan} />

      {/* Tasks */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Tasks</CardTitle>
        </CardHeader>
        <CardContent>
          {fix.tasks.length === 0 ? (
            <p className="text-muted-foreground text-sm">No tasks defined</p>
          ) : (
            <div className="space-y-2">
              {fix.tasks.map((task, index) => (
                <TaskItem key={task.id} task={task} index={index} repoId={repoId} />
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default FixDetail;
